INSERT INTO incident_notes VALUES ('2026-09-03', 'cpu', 'CPU tier saturating at lunchtime; p95 token latency doubled but no errors surfaced.', 'capacity');
INSERT INTO incident_notes VALUES ('2026-09-05', 'gpu', 'Semantic router confidence threshold mis-set after a config reload, sending trivial prompts to the GPU tier.', 'configuration');
INSERT INTO incident_notes VALUES ('2026-09-08', 'gpu', 'KEDA scaledownPeriod misconfigured to 60s: the GPU pool scaled to zero between bursts, every request paid a cold start and client retries snowballed into a retry storm.', 'configuration');
INSERT INTO incident_notes VALUES ('2026-09-11', 'cpu', 'Intermittent DNS resolution failures from the retrieval pod toward Qdrant.', 'network');
INSERT INTO incident_notes VALUES ('2026-09-12', 'gpu', 'Envoy upstream reset spike during a cross-zone metadata server flap.', 'network');
INSERT INTO incident_notes VALUES ('2026-09-14', 'gpu', 'Users reported the chat UI listing stale model names after the router rollout.', 'ux');
INSERT INTO incident_notes VALUES ('2026-09-17', 'gpu', 'GPU OOM during long-context batching; workers crashed and the request queue backlog took 40 minutes to drain.', 'capacity');
INSERT INTO incident_notes VALUES ('2026-09-19', 'cpu', 'Document ingestion CronJob overlapped the traffic peak; CPU throttling raised token latency.', 'capacity');
INSERT INTO incident_notes VALUES ('2026-09-21', 'gpu', 'Brief latency blip traced to a one-off client-side retry loop; no platform fault found.', 'ux');
INSERT INTO incident_notes VALUES ('2026-09-24', 'gpu', 'L4 GPU quota exhausted in us-central1-a; new pods stuck Pending while the pool tried to scale up.', 'capacity');
INSERT INTO incident_notes VALUES ('2026-09-26', 'cpu', 'Planned router config reload completed cleanly; no user impact.', 'configuration');
INSERT INTO incident_notes VALUES ('2026-09-29', 'cpu', 'Queue depth briefly elevated during a batch evaluation run.', 'capacity');
